package in.littlelist;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ProductPreviewTest {
 final ProductPreview preview=new ProductPreview(new ObjectMapper());
 @Test void amazonCorePriceAndLandingImage(){var p=preview.parse(Jsoup.parse("<span id='productTitle'>First Kick Kids Blanket</span><div id='corePriceDisplay_desktop_feature_div'><span class='a-price'><span class='a-offscreen'> </span></span></div><div id='corePrice_feature_div'><span class='a-price'><span class='a-offscreen'>₹499.00</span></span><span class='a-price a-text-price'><span class='a-offscreen'>₹999.00</span></span></div><img id='landingImage' data-old-hires='https://m.media-amazon.com/images/I/61zQfj6RxDL._SL1024_.jpg'>"),"https://www.amazon.in/First-Kick-Blankets-Printed-Blanket/dp/B0FH79G2MW/");assertEquals("499",p.price());assertTrue(p.imageUrl().endsWith("_SL1024_.jpg"));}
 @Test void amazonMobileImageFallback(){var p=preview.parse(Jsoup.parse("<span id='productTitle'>Baby towel</span><img id='landingImage' data-old-hires='https://m.media-amazon.com/images/I/towel.jpg'>"),"https://www.amazon.in/gp/aw/d/B012345678");assertEquals("Baby towel",p.name());assertTrue(p.imageUrl().endsWith("towel.jpg"));}
 @Test void sessionQuotaAndNoStore(){var session=new org.springframework.mock.web.MockHttpSession();for(int i=0;i<10;i++){var r=preview.preview(new ProductPreview.Input("https://unsupported.example/product"),session);assertEquals("no-store",r.getHeaders().getCacheControl());assertEquals("",r.getBody().name());}var ex=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->preview.preview(new ProductPreview.Input("https://unsupported.example/product"),session));assertEquals(429,ex.getStatusCode().value());}
 @Test void structuredProductAndIndianPrice(){var p=preview.parse(Jsoup.parse("<script type='application/ld+json'>{\"@type\":\"Product\",\"name\":\"Cotton & care\",\"image\":[\"https://m.media-amazon.com/images/I/gift.jpg\"],\"offers\":{\"price\":\"1,299.50\",\"priceCurrency\":\"INR\"},\"color\":\"Sage\"}</script>"),"https://www.amazon.in/dp/B012345678");assertEquals("Cotton & care",p.name());assertEquals("1299.50",p.price());assertEquals("Sage",p.variant());assertTrue(p.imageUrl().endsWith("gift.jpg"));}
 @Test void retailerMetadataFallback(){for(String url:new String[]{"https://www.flipkart.com/gift/p/test","https://www.firstcry.com/brand/gift/123/product-detail"}){var p=preview.parse(Jsoup.parse("<h1>Baby book</h1><meta property='og:image' content='https://cdn.fcglcdn.com/brainbees/images/products/book.jpg'><meta property='product:price:currency' content='INR'><meta property='product:price:amount' content='499'>"),url);assertEquals("Baby book",p.name());assertEquals("499",p.price());assertFalse(p.imageUrl().isEmpty());}}
 @Test void ambiguousOrForeignOffersStayBlank(){for(String offer:new String[]{"{\"price\":99,\"priceCurrency\":\"USD\"}","[{\"price\":99,\"priceCurrency\":\"INR\"}]","{\"lowPrice\":99,\"priceCurrency\":\"INR\"}"}){var p=preview.parse(Jsoup.parse("<script type='application/ld+json'>{\"@type\":\"Product\",\"name\":\"Book\",\"offers\":"+offer+"}</script>"),"https://www.amazon.in/dp/B012345678");assertEquals("",p.price());}}
 @Test void captchaAndMultipleProductsAreNotGifts(){assertEquals("",preview.parse(Jsoup.parse("<title>Robot check</title><form>Captcha</form>"),"https://www.amazon.in/dp/B012345678").name());assertEquals("",preview.parse(Jsoup.parse("<script type='application/ld+json'>[{\"@type\":\"Product\",\"name\":\"A\"},{\"@type\":\"Product\",\"name\":\"B\"}]</script>"),"https://www.flipkart.com/search").name());}
 @Test void rejectsUnsafeUrlsAndImageHosts(){for(String url:new String[]{"http://www.amazon.in/","https://localhost/","https://169.254.169.254/","https://www.amazon.in.evil.test/","https://user:secret@www.amazon.in/","https://www.amazon.in:8080/","file:///etc/passwd"})assertThrows(IllegalArgumentException.class,()->ProductPreview.allowed(url));assertEquals("",ProductPreview.image("https://evil.test/image.jpg"));assertEquals("",ProductPreview.image("javascript:alert(1)"));assertEquals("",ProductPreview.image("https://m.media-amazon.com@evil.test/image.jpg"));assertEquals("",ProductPreview.price("499 per month"));assertEquals("",ProductPreview.price("21474837"));}
}
